const urSets=$('#urSets'),urMeta=$('#urMeta'),urQ=$('#urQ'),urC=$('#urC'),urI=$('#urI');let us=0,uq=0,uT=null,uAuto=true,uOn=false;
urSets.innerHTML=SETS.map((s,i)=>'<button role="tab" data-s="'+i+'">'+s.k+'</button>').join('');
function setSet(i){us=i;const s=SETS[i];$$('button',urSets).forEach((b,k)=>b.classList.toggle('on',k===i));
  urMeta.innerHTML=s.meta.map(m=>'<div><span>'+m[0]+'</span><b>'+m[1]+'</b></div>').join('');
  urQ.innerHTML=s.qs.map((q,k)=>'<button data-q="'+k+'"><i>'+(k+1)+'</i>'+q.l+'<span class="pg"></span></button>').join('');
  $$('button',urQ).forEach(b=>b.addEventListener('click',()=>{uAuto=false;setUQ(+b.dataset.q);}));
  setUQ(0);}
function setUQ(i){uq=i;const s=SETS[us],q=s.qs[i];
  $$('button',urQ).forEach((b,k)=>{b.classList.toggle('on',k===i);const pg=$('.pg',b);pg.style.transition='none';pg.style.width='0';});
  const b0=$$('button',urQ)[i];if(b0&&urQ.scrollWidth>urQ.clientWidth)urQ.scrollTo({left:b0.offsetLeft-20,behavior:'smooth'});
  swap(urC,()=>{urC.innerHTML='<div class="urc-g"><div class="urc-m"><span class="q">'+q.q+'</span><h5>'+q.h+'</h5><div class="body"></div><span class="src" style="margin-top:auto">'+s.src+'</span></div><aside class="urc-n"><span class="src">What it tells us</span><p>'+(q.n||'')+'</p></aside></div>';
    const body=$('.body',urC);if(q.t==='donut')donut(body,q.d);else if(q.t==='bars')bars(body,q.rows,q.max,q.den);else if(q.t==='stack')stack(body,q.d);else ahp(body);});
  swap(urI,()=>{urI.innerHTML='<span class="src">Key insight</span><div class="big">'+q.big+'</div><p class="lbl2">'+q.bl+'</p><div class="imp"><span>Design implication</span><b>→ '+q.imp+'</b></div>';});
  clearTimeout(uT);
  if(uAuto&&uOn&&!RM){const pg=$('.pg',b0);requestAnimationFrame(()=>{pg.style.transition='width 4.2s linear';pg.style.width='100%';});
    uT=setTimeout(()=>{if(uq+1<SETS[us].qs.length)setUQ(uq+1);else setSet((us+1)%SETS.length);},4200);}
}
$$('button',urSets).forEach(b=>b.addEventListener('click',()=>{uAuto=false;clearTimeout(uT);setSet(+b.dataset.s);}));
